"""WikiVerifier — cross-checks wiki claims against source text.

AIV v5.3 — BATCH-123 TASK-02, BATCH-131 TASK-01
HB-02: Verifier does NOT modify the wiki entry — only returns a new one with scores.
HB-03: verify() returns a deep copy; original is never mutated.
"""

from __future__ import annotations

import copy
import json
import logging
import re
from pathlib import Path

from backend.pipeline.wiki.models import WikiEntry

logger = logging.getLogger(__name__)

_PROMPT_PATH = Path(__file__).parent / "prompts" / "wiki_verification.md"


class WikiVerifier:
    """Verifies wiki entries against source paper text.

    Checks that factual claims in the wiki are supported by the source text.
    Uses LLM verification when a provider is available; falls back to keyword
    overlap otherwise or on LLM failure.
    Does NOT modify the input wiki (HB-02 / HB-03).
    """

    def __init__(self, provider=None) -> None:
        self._provider = provider
        self._prompt_template: str | None = None

    # ── Prompt loading ──────────────────────────────────

    def _load_prompt_template(self) -> str:
        """Load and cache the verification prompt template (A-03)."""
        if self._prompt_template is None:
            try:
                self._prompt_template = _PROMPT_PATH.read_text(encoding="utf-8")
            except FileNotFoundError:
                logger.warning("Verification prompt template not found at %s", _PROMPT_PATH)
                self._prompt_template = (
                    "Given the following CLAIM and SOURCE TEXT, judge whether the claim "
                    "is supported. ONLY answer based on the source text. "
                    "Return JSON: {{\"supported\": true/false, \"reasoning\": \"explanation\"}}\n\n"
                    "CLAIM:\n{claim}\n\nSOURCE TEXT:\n{source_text}"
                )
        return self._prompt_template

    # ── Public API ──────────────────────────────────────

    async def verify(self, wiki: WikiEntry, source_text: str) -> WikiEntry:
        """Verify a wiki entry against source text.

        Returns a NEW WikiEntry with quality_score and unsupported_claims set.
        Original wiki is NOT modified (HB-02 / HB-03).
        """
        # Deep copy to avoid mutation (HB-02 / HB-03)
        result = copy.deepcopy(wiki)
        unsupported: list[str] = []

        if not source_text or not source_text.strip():
            result.quality_score = 0.1
            result.unsupported_claims = ["Empty source text — cannot verify"]
            return result

        # Collect all factual claims from the wiki
        claims = self._extract_claims(wiki)
        source_lower = source_text.lower()

        verified = 0
        for claim in claims:
            supported = False

            if self._provider is not None:
                # Try LLM verification first
                try:
                    llm_result = await self._verify_claim_with_llm(claim, source_text)
                    if llm_result.get("supported") is None:
                        # LLM failed — fall back to keyword
                        supported = self._claim_supported(claim, source_lower)
                    else:
                        supported = llm_result["supported"]
                        if not supported:
                            reason = llm_result.get("reasoning", claim)
                            unsupported.append(f"{claim} — {reason}")
                except Exception:
                    # Any LLM error — fall back to keyword (HB-01)
                    logger.debug("LLM verification failed for claim, falling back to keyword")
                    supported = self._claim_supported(claim, source_lower)
            else:
                # No provider — use keyword overlap
                supported = self._claim_supported(claim, source_lower)

            if supported and (self._provider is None or unsupported and unsupported[-1].startswith(claim)):
                # Already added above for LLM-rejected claims
                pass
            elif supported:
                verified += 1
            else:
                if not unsupported or not unsupported[-1].startswith(claim):
                    unsupported.append(claim)

        total = max(len(claims), 1)
        result.quality_score = verified / total
        result.unsupported_claims = unsupported
        return result

    # ── LLM Verification ────────────────────────────────

    async def _verify_claim_with_llm(self, claim: str, source: str) -> dict:
        """Verify a single claim using the LLM provider.

        Returns {"supported": bool, "reasoning": str}.
        On any failure returns {"supported": None, "reasoning": "LLM verification failed"}.
        """
        template = self._load_prompt_template()
        prompt = template.format(claim=claim, source_text=source)

        messages = [
            {"role": "system", "content": "You are a precise claim verification assistant."},
            {"role": "user", "content": prompt},
        ]

        response: str = await self._provider.complete(
            messages, temperature=0.1, max_tokens=512,
        )

        # Parse JSON from response string
        return self._parse_llm_response(response)

    @staticmethod
    def _parse_llm_response(response: str) -> dict:
        """Parse the LLM response string into a verification dict.

        Handles:
        - Clean JSON: {"supported": true, "reasoning": "..."}
        - JSON embedded in markdown code fences
        - Malformed responses (returns supported=None)
        """
        text = response.strip()

        # Try direct parse first
        try:
            result = json.loads(text)
            if isinstance(result, dict) and "supported" in result:
                return {
                    "supported": result["supported"],
                    "reasoning": str(result.get("reasoning", "")),
                }
        except json.JSONDecodeError:
            pass

        # Try extracting JSON from markdown code fences
        json_match = re.search(r"```(?:json)?\s*(\{.*?\})\s*```", text, re.DOTALL)
        if json_match:
            try:
                result = json.loads(json_match.group(1))
                if isinstance(result, dict) and "supported" in result:
                    return {
                        "supported": result["supported"],
                        "reasoning": str(result.get("reasoning", "")),
                    }
            except json.JSONDecodeError:
                pass

        # Try finding any JSON object in the response
        brace_match = re.search(r"\{[^{}]*\}", text, re.DOTALL)
        if brace_match:
            try:
                result = json.loads(brace_match.group(0))
                if isinstance(result, dict) and "supported" in result:
                    return {
                        "supported": result["supported"],
                        "reasoning": str(result.get("reasoning", "")),
                    }
            except json.JSONDecodeError:
                pass

        # All parsing failed
        return {"supported": None, "reasoning": "LLM verification failed"}

    # ── Claim Extraction ────────────────────────────────

    @staticmethod
    def _extract_claims(wiki: WikiEntry) -> list[str]:
        """Extract verifiable claims from a wiki entry."""
        claims: list[str] = []

        # Method details are factual claims
        if wiki.proposed_method:
            claims.append(wiki.proposed_method)
        for insight in wiki.key_insights:
            claims.append(insight)
        for exp in wiki.experiments:
            # Each experiment result is a factual claim
            parts = []
            if isinstance(exp, dict):
                if "dataset" in exp:
                    parts.append(f"dataset: {exp['dataset']}")
                if "metric" in exp and "value" in exp:
                    parts.append(f"{exp['metric']}: {exp['value']}")
            if parts:
                claims.append("; ".join(parts))

        return claims

    # ── Keyword Overlap Fallback ────────────────────────

    @staticmethod
    def _claim_supported_keyword(claim: str, source_lower: str) -> bool:
        """Check if a claim is supported by the source text.

        Uses keyword overlap: if >=40% of content words from the claim
        appear in the source, it's considered supported.
        """
        claim_lower = claim.lower()
        # Extract significant words (length > 3)
        claim_words = {w for w in re.findall(r"[a-z0-9]+", claim_lower) if len(w) > 3}
        if not claim_words:
            return True  # Empty claim is trivially supported

        found = sum(1 for w in claim_words if w in source_lower)
        ratio = found / len(claim_words)
        return ratio >= 0.4

    @staticmethod
    def _claim_supported(claim: str, source_lower: str) -> bool:
        """Alias for _claim_supported_keyword — backward-compatible entry point."""
        return WikiVerifier._claim_supported_keyword(claim, source_lower)

